static std::string hex(const CodeBuffer& b) { std::string s; char t[3]; for (uint8_t c : b) { snprintf(t, 3, "%02x", c); s += t; } return s; }
static const char* kKind[] = {"addsd","subsd","mulsd","divsd","movsd xmm,xmm","comisd","ucomisd","roundsd","xorpd","movsd xmm,[rbp+i*8+d]","movsd [rbp+i*8+d],xmm","cvtsi2sd","cvttsd2si","movsd xmm,[rbp+d]","movsd [rbp+d],xmm"};
int main() {
    constexpr int32_t kDisp = 0x1000;  // forces disp32 so rbp-relative forms match as exactly
    int bad = 0, n = 0;
    for (const Row& r : kRows) {
        CodeBuffer b; Xmm A = static_cast<Xmm>(r.a); Xmm B = static_cast<Xmm>(r.b); Reg G = static_cast<Reg>(r.b);
        switch (r.kind) {
            case 0: emit_addsd(b, A, B); break;   case 1: emit_subsd(b, A, B); break;
            case 2: emit_mulsd(b, A, B); break;   case 3: emit_divsd(b, A, B); break;
            case 4: emit_movsd_xmm_xmm(b, A, B); break;
            case 5: emit_comisd(b, A, B); break;  case 6: emit_ucomisd(b, A, B); break;
            case 7: emit_roundsd_imm8(b, A, B, 0x0b); break;
            case 8: emit_xorpd_zero(b, A); break;
            case 9: emit_movsd_xmm_rbp_scaled(b, A, G, kDisp); break;
            case 10: emit_movsd_rbp_scaled(b, A, G, kDisp); break;
            case 11: emit_cvtsi2sd(b, A, G); break;
            case 12: emit_cvttsd2si(b, G, A); break;
            case 13: emit_movsd_xmm_rbp(b, A, kDisp); break;
            case 14: emit_movsd_rbp_mem(b, A, kDisp); break;
        }
        ++n;
        if (hex(b) != r.hex) { if (++bad <= 20) printf("FAIL %s a=%d b=%d\n  want: %s\n  got : %s\n", kKind[r.kind], r.a, r.b, r.hex, hex(b).c_str()); }
    }
    if (bad) { printf("FAIL: %d of %d SSE encodings differ from GNU as\n", bad, n); return 1; }
    printf("PASS: %d SSE encodings identical to GNU as\n", n);
    return 0;
}
